using System.IO.Pipes;
using System.Text;
using System.Text.Json;
using System.Windows;
using YoWidgets;
internal static class WidgetIpcChecks
{
    static void Require(bool c,string text)=>LiveVoiceChecks.Require(c,text);
    internal static async Task Client(string root)
    {
        using var token=new CancellationTokenSource(TimeSpan.FromSeconds(8));using var client=new NamedPipeClientStream(".",WidgetIpcServer.Name(root),PipeDirection.InOut,PipeOptions.Asynchronous);await client.ConnectAsync(token.Token);using var writer=new StreamWriter(client,new UTF8Encoding(false),1024,true){AutoFlush=true};using var reader=new StreamReader(client,Encoding.UTF8,false,1024,true);await writer.WriteLineAsync("{\"action\":\"state\",\"args\":{}}");var line=await reader.ReadLineAsync(token.Token);using var json=JsonDocument.Parse(line!);if(!json.RootElement.GetProperty("ok").GetBoolean())throw new Exception("IPC state failed");Console.WriteLine("CHILD IPC OK");
    }
    internal static void Run()
    {
        var root=Path.GetFullPath("artifacts/widget-ipc/run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var app=new App{ShutdownMode=ShutdownMode.OnExplicitShutdown};typeof(App).GetProperty(nameof(App.DataRoot))!.SetValue(null,root);Ui.Theme();var manager=new WidgetManager(root,true);typeof(App).GetProperty(nameof(App.Manager))!.SetValue(app,manager);Exception? failure=null;
        app.Startup+=async(_,_)=>{try{
            using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(35));var token=timeout.Token;using var ipc=new WidgetIpcServer(manager.Commands,app.Dispatcher,root);var calendar=WidgetCards.Calendar(manager);var calendarWindow=new Window{Content=calendar,Width=400,Height=210,Title="YoWidgets calendar fixture"};calendarWindow.Show();
            async Task<JsonElement> Request(string action,object args){using var client=new NamedPipeClientStream(".",WidgetIpcServer.Name(root),PipeDirection.InOut,PipeOptions.Asynchronous);await client.ConnectAsync(token);using var reader=new StreamReader(client,Encoding.UTF8,false,1024,true);using var writer=new StreamWriter(client,new UTF8Encoding(false),1024,true){AutoFlush=true};await writer.WriteLineAsync(JsonSerializer.Serialize(new{action,args}).AsMemory(),token);var result=await reader.ReadLineAsync(token);return JsonSerializer.Deserialize<JsonElement>(result!);}
            var state=await Request("state",new{});Require(state.GetProperty("ok").GetBoolean()&&!state.GetRawText().Contains("KeyProtected")&&!state.GetRawText().Contains("AiKey"),"IPC state exposed credentials or failed");Console.WriteLine("PASS widget IPC: real current-user named pipe reaches UI dispatcher without exposing settings/key material");
            var info=new System.Diagnostics.ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};info.ArgumentList.Add("--widget-ipc-client");info.ArgumentList.Add(root);using(var child=System.Diagnostics.Process.Start(info)!){var output=await child.StandardOutput.ReadToEndAsync(token);await child.WaitForExitAsync(token);Require(child.ExitCode==0&&output.Contains("CHILD IPC OK"),"Separate-process IPC client failed");}Console.WriteLine("PASS widget IPC: separate hidden process connects through the named pipe and receives real state");
            var added=await Request("calendar_add",new{title="IPC fixture",due=DateTimeOffset.Now.AddDays(2).ToString("O")});Require(added.GetProperty("ok").GetBoolean()&&manager.Settings.CalendarTasks.Count==1,"Calendar add did not persist");await LiveVoiceChecks.Until(()=>Labels(calendar).Any(t=>t.Text=="1 task"));var task=manager.Settings.CalendarTasks.Single();var loaded=new SettingsStore(Path.Combine(root,"settings.json")).Load();Require(loaded.CalendarTasks.Single().Title=="IPC fixture","Calendar task lost after reload");var completed=await Request("calendar_complete",new{id=task.Id});Require(completed.GetProperty("ok").GetBoolean()&&manager.Settings.CalendarTasks[0].Completed,"Calendar completion did not reach widget state");await LiveVoiceChecks.Until(()=>Labels(calendar).All(t=>t.Text!="1 task"));Console.WriteLine("PASS widget calendar: IPC add/complete updates the actual calendar view, saves real tasks and survives settings reload");
            var invalid=await Request("calendar_add",new{title="bad",due="tomorrow at five"});Require(!invalid.GetProperty("ok").GetBoolean()&&manager.Settings.CalendarTasks.Count==1,"Ambiguous calendar time mutated data");var ambiguous=await Request("calendar_add",new{title="bad culture",due="01/05/2026 18:00+03:00"});Require(!ambiguous.GetProperty("ok").GetBoolean()&&manager.Settings.CalendarTasks.Count==1,"Non-ISO date mutated data");var denied=await Request("execute_task",new{task="untrusted IPC payload"});Require(!denied.GetProperty("ok").GetBoolean(),"IPC exposed arbitrary agent execution");Console.WriteLine("PASS widget IPC boundary: invalid dates and arbitrary task/shell actions are rejected without mutation");
            var focus=await Request("focus",new{minutes=1});Require(focus.GetProperty("ok").GetBoolean()&&manager.Data.FocusEnd.HasValue,"Focus start failed");await Request("focus",new{minutes=0});Require(!manager.Data.FocusEnd.HasValue,"Focus stop failed");await Request("status",new{text="YoWidgets IPC fixture"});Console.WriteLine("PASS widget actions: focus start/stop and real desktop status overlay");
            calendarWindow.Close();ipc.Dispose();try{await ipc.Completion;}catch(OperationCanceledException){}Console.WriteLine("PASS widget IPC: cancellation closes listener cleanly");
        }catch(Exception e){failure=e;}finally{manager.Dispose();app.Shutdown();}};app.Run();if(failure!=null)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure).Throw();
    }
    static IEnumerable<System.Windows.Controls.TextBlock> Labels(DependencyObject root){if(root is System.Windows.Controls.TextBlock text)yield return text;for(var i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)foreach(var item in Labels(System.Windows.Media.VisualTreeHelper.GetChild(root,i)))yield return item;}
}
